export const MONUMENTS = JSON.parse("[{\"id\":\"n6358872948\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-1566.5,\"z\":-390.6,\"subject\":\"Q4424524\",\"inscription\":\"В этом доме в 1830х годах находились библиотека и книжная лавка известного книгоиздателя Александра Филипповича Смирдина. Здесь встречались А.С. Пушкин, И.А. Крылов, В.А. Жуковский, Н.В. Гоголь и другие русские писатели и поэты.\"},{\"id\":\"n6893148685\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Сфинкс\",\"x\":-1728,\"z\":-373.8,\"material\":\"granite\"},{\"id\":\"n6903094628\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Сфинкс\",\"x\":-1728.3,\"z\":-372.7,\"material\":\"granite\"},{\"id\":\"n13272985734\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-1539.7,\"z\":-383.4},{\"id\":\"n4683728170\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Н. И. Вавилову\",\"x\":-2021.9,\"z\":-437.9,\"subject\":\"Q214926\",\"inscription\":\"В этом доме с 1928 по 1940 г. жил выдающийся биолог, академик Николай Иванович Вавилов\"},{\"id\":\"n4683728171\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Н. П. Акимову\",\"x\":-2028.7,\"z\":-411.6,\"subject\":\"Q1185061\",\"inscription\":\"В этом доме с 1945 г. по 1967 г. жил народный артист СССР Николай Павлович Акимов\"},{\"id\":\"n4683728172\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. Н. Кононову\",\"x\":-2053.9,\"z\":-412.7,\"subject\":\"Q765371\",\"inscription\":\"В этом доме жил с 1968 по 1986 год выдающийся учёный-востоковед академик Андрей Николаевич Кононов\"},{\"id\":\"n10126606281\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. С. Грибоедову\",\"x\":-1891.8,\"z\":-384.3,\"subject\":\"Q15001\",\"inscription\":\"В этом доме в 1828 году жил Александр Сергеевич Грибоедов\"},{\"id\":\"n5854740072\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Ф. Э. Дзержинскому\",\"x\":-2277.2,\"z\":-438,\"subject\":\"Q188570\",\"inscription\":\"В этом доме с 7 (20) декабря 1917 года по 10 (23) марта 1918 года находилась Всероссийская Чрезвычайная Комиссия по борьбе с контрреволюцией и саботажем, которую возглавлял [...] Феликс Эдмундович Дзержинский\",\"description\":\"Из-за ограничений на длину текста пропущен следующий фрагмент: \\\"выдающийся деятель Коммунистической партии и Советского государства, ближайший соратник В.И. Ленина\\\"\"},{\"id\":\"n5854766833\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. О. Дунаевскому\",\"x\":-2257.7,\"z\":-412.2,\"subject\":\"Q638638\",\"inscription\":\"В этом доме с 1936 по 1941 год жил и работал выдающийся композитор Исаак Осипович Дунаевский\"},{\"id\":\"n5854766836\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. Я. Вагановой\",\"x\":-2250.7,\"z\":-402.8,\"subject\":\"Q236413\",\"inscription\":\"Здесь с 1937 года по 1951 год жила Агриппина Яковлевна Ваганова, профессор, крупнейший деятель советской хореографии\"},{\"id\":\"n5854766837\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"С. П. Преображенской\",\"x\":-2249.2,\"z\":-400.8,\"subject\":\"Q4377282\",\"inscription\":\"В этом доме с 1937 по 1966 год жила народная артистка СССР, лауреат Государственных премий СССР, профессор Софья Петровна Преображенская\"},{\"id\":\"n5854766838\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. В. Ершову\",\"x\":-2253.3,\"z\":-406.3,\"subject\":\"Q4176892\",\"inscription\":\"В этом доме с 1931 по 1941 год жил великий русский певец, профессор Ленинградской консерватории, народный артист СССР Иван Васильевич Ершов\"},{\"id\":\"n5854766842\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Г. А. Алиеву\",\"x\":-2229.9,\"z\":-375.5,\"subject\":\"Q157451\",\"inscription\":\"В этом доме, в Высшей школе МГБ СССР в 1949-1950 гг. учился выдающийся государственный деятель, президент Азербайджанской республики Гейдар Алиевич Алиев\"},{\"id\":\"n1882590592\",\"kind\":\"memorial\",\"sub\":\"bust\",\"name\":\"Н. М. Пржевальский\",\"x\":-2450.5,\"z\":-404.2,\"h\":4.8,\"material\":\"bronze\",\"startDate\":\"1892-10-20\",\"subject\":\"Q192442\",\"artist\":\"И. Н. Шредер\",\"inscription\":\"Пржевальскому, первому исследователю природы Центральной Азии\",\"wikidata\":\"Q21643738\",\"wikipedia\":\"ru:Памятник Пржевальскому (Санкт-Петербург)\"},{\"id\":\"n3511128409\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Геракл Фарнезский\",\"x\":-2547.8,\"z\":-389,\"startDate\":\"2014\",\"artist\":\"П. Трискорни\",\"description\":\"Точная копия мраморной статуи 1833 года\",\"wikidata\":\"Q374591\",\"wikipedia\":\"ru:Геркулес Фарнезский\"},{\"id\":\"n5661710566\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. Н. Крамскому\",\"x\":-2378.3,\"z\":-371.2,\"subject\":\"Q207758\",\"inscription\":\"В этом доме с 1866 по 1870 год жил и работал крупнейший русский художник Иван Николаевич Крамской. Здесь же помещалась организованная им артель, объединившая передовых художников-реалистов 60-х годов\"},{\"id\":\"n5724836272\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-2778.6,\"z\":-364.3,\"subject\":\"Q126306\",\"inscription\":\"На этой площади (б. Сенатской) 14 (26) декабря 1825 года произошло восстание декабристов, первое в России вооруженное выступление против самодержавия\"},{\"id\":\"n1191476119\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Древнеегипетский сфинкс\",\"x\":-3397.4,\"z\":-497,\"startDate\":\"C14 BC\",\"wikidata\":\"Q2657856\",\"wikipedia\":\"ru:Сфинксы на Университетской набережной\"},{\"id\":\"n1191476126\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Древнеегипетский сфинкс\",\"x\":-3360.5,\"z\":-518.7,\"startDate\":\"C14 BC\",\"wikidata\":\"Q2657856\",\"wikipedia\":\"ru:Сфинксы на Университетской набережной\"},{\"id\":\"n8075917053\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Минерва\",\"x\":-3406.6,\"z\":-556.1},{\"id\":\"n1271441034\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"И. И. Шувалову\",\"x\":-3433,\"z\":-599.3,\"startDate\":\"2003\",\"subject\":\"Q659395\",\"artist\":\"З. К. Церетели\"},{\"id\":\"n2586283111\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"Д. Трезини\",\"x\":-3532.3,\"z\":-486.5,\"wikidata\":\"Q25395360\",\"wikipedia\":\"ru:Памятник Трезини (Санкт-Петербург)\"}]");
